'use strict';

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v, digits = 0) => v == null ? 'Unavailable' : Number(v).toLocaleString('en-GB', {maximumFractionDigits:digits, minimumFractionDigits:digits});
const pct = (v, digits = 1) => `${num(v * 100, digits)}%`;
const dateLabel = value => new Date(value + 'T12:00:00').toLocaleDateString('en-GB', {day:'2-digit',month:'long',year:'numeric'});
const labels = {high:'High risk',medium:'Medium risk',low:'Low risk',not_assessed:'Not assessed',strong:'Strong',acceptable:'Acceptable',limited:'Limited',blocked:'Blocked',pending:'Pending review',accepted:'Accepted',edited:'Edited',rejected:'Rejected',on_track:'On track',at_risk:'At risk',off_track:'Off track',completed:'Completed',planned:'Planned'};
const badge = (status, text) => `<span class="badge ${esc(status)}">${esc(text || labels[status] || status)}</span>`;
const icon = (name, size=16) => {
  const paths = {upload:'M8 11V2M5 5l3-3 3 3M2 10v4h12v-4',search:'M7 1a6 6 0 1 0 0 12A6 6 0 0 0 7 1Zm4 10 4 4',download:'M8 1v10M5 8l3 3 3-3M2 12v3h12v-3',print:'M4 5V1h8v4M4 12H1V5h14v7h-3M4 9h8v6H4zM12 7h1',arrow:'M4 8h8M8 4l4 4-4 4',risk:'M8 2 1 14h14L8 2Zm0 4v4m0 2v.1',report:'M4 1h6l3 3v11H3V1h1Zm5 0v4h4M5 8h6M5 11h6',transfer:'M1 5h13m-4-4 4 4-4 4M15 11H2m4-4-4 4 4 4',quality:'M8 1 2 3v5c0 3 6 7 6 7s6-4 6-7V3L8 1Zm-3 7 2 2 4-4',grid:'M1 1h5v5H1zM10 1h5v5h-5zM1 10h5v5H1zM10 10h5v5h-5z',clock:'M8 1a7 7 0 1 0 0 14A7 7 0 0 0 8 1Zm0 3v4l3 2'};
  return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.arrow}"/></svg>`;
};

const state = {data:null, page:'overview', window:14, filters:{facility:'',medicine:'',risk:'',quality:'',search:''}, plannerTab:'all',reportTab:'briefing', aiTab:'copilot',copilotAnswer:null,monitor:null,question:'Which facilities are most likely to run out of malaria medicines?', aiDraft:null, draft:{narrative_mode:'gemini',prepared_by:'District supply team',management_note:'',selected_findings:null,actions:[]}, draftLoaded:false, noticeTimer:null, email:null};

async function api(path, options={}) {
  const response = await fetch('/api' + path, {credentials:'same-origin',...options, headers:{...(options.body && !(options.body instanceof FormData) ? {'Content-Type':'application/json'} : {}),...options.headers}});
  if (!response.ok) {
    const error = await response.json().catch(() => ({detail:'The request could not be completed.'}));
    const message = Array.isArray(error.detail) ? error.detail.map(e => `${e.loc?.slice(-1).join('') || 'Field'}: ${e.msg}`).join('\n') : error.detail;
    throw new Error(message || 'The workspace is temporarily unavailable.');
  }
  if (options.raw) return response;
  return response.json();
}

function announce(message) { $('#announcer').textContent = message; }
function toast(message) { const node=$('#notice'); node.textContent=message; node.hidden=false; clearTimeout(state.noticeTimer); state.noticeTimer=setTimeout(() => {node.hidden=true;},5000); announce(message); }
function showError(message, root=document) { const el=$('[data-error]',root); if(el){el.textContent=message;el.hidden=false;el.focus();}else toast(message); }
async function refresh() {
  state.data = await api(`/risk/summary?window=${state.window}`);
  $('#districtLabel').innerHTML = `${esc(state.data.context.district)} <span aria-hidden="true">⌄</span>`;
  render();
}

const pageDetails = {
 overview:['DISTRICT BRIEFING','District overview.','The signals that matter. The evidence behind them. The next action to review.'],
 risks:['SIGNAL → EVIDENCE','Risk explorer.','Investigate stock cover, supply delays and the reliability of each finding.'],
 planner:['EVIDENCE → REVIEWED ACTION','Redistribution planner.','Find a feasible route. Protect both facilities. Record the human decision.'],
 quality:['THE EVIDENCE FOUNDATION','Data quality.','See what the records support, where they fall short and what needs correcting.'],
 ai:['MODEL RECORD & REVIEW FEEDBACK','Model performance.','Inspect forecast performance, changing evidence and the decisions recorded by the team.'],
 report:['ACCOUNTABILITY & FOLLOW-THROUGH','Supply brief.','A complete district readout, with clear decisions, named owners and next steps.']
};

function heading(page) {
 const [overline,title,desc]=pageDetails[page], c=state.data.context;
 return `<div class="page-heading"><div><div class="eyebrow"><span class="rule"></span>${overline}</div><h1>${title}</h1><p class="page-description">${desc}</p></div><div class="heading-side"><div class="date-label">REPORTING CUT-OFF · ${esc(dateLabel(c.cutoff))}</div><div><span class="window-label">Forecast horizon</span><div class="window-control" role="group" aria-label="Forecast horizon"><button data-action="window" data-window="7" class="${state.window===7?'active':''}" aria-pressed="${state.window===7}">7 days</button><button data-action="window" data-window="14" class="${state.window===14?'active':''}" aria-pressed="${state.window===14}">14 days</button><button data-action="window" data-window="30" class="${state.window===30?'active':''}" aria-pressed="${state.window===30}">30 days</button></div></div></div></div><div class="context-strip"><span>${esc(c.district)} · 10 facilities</span><span class="separator"></span><span>${state.data.pairs.length} facility–medicine pairs</span><span class="separator"></span><span>Data ${esc(c.data_version)}</span><span class="context-model">${icon('grid',11)} <span>${esc(c.model)}</span></span></div>`;
}

function kpi(label, value, unit, foot, action, tone='', iconName='arrow') {
 return `<button class="kpi" data-action="${action}"><div class="kpi-label">${label}${icon(iconName,14)}</div><div class="kpi-value ${tone}">${value}<span class="value-unit">${unit}</span></div><div class="kpi-foot">${foot}</div></button>`;
}

function riskTable(pairs, full=false) {
 if(!pairs.length) return `<div class="empty"><h2>No matching findings.</h2><p>Adjust the facility, medicine, risk or quality filters to see more evidence.</p><button class="button secondary" data-action="clear-filters">Clear filters</button></div>`;
 return `<div class="table-scroll"><table class="risk-table"><caption class="sr-only">Facility and medicine stock risks, ranked by urgency. Actual stock cover is compared with safety stock.</caption><thead><tr><th class="risk-column" scope="col">Risk</th><th scope="col">Facility / medicine</th><th scope="col">Actual stock cover</th><th class="prediction-column" scope="col">Predicted risk</th><th class="quality-column" scope="col">Evidence quality</th>${full?'<th class="evidence-column" scope="col">Primary bottleneck</th>':''}<th scope="col"><span class="sr-only">Investigate</span></th></tr></thead><tbody>${pairs.map(p=>`<tr><td class="risk-column">${badge(p.risk)}</td><td><span class="mobile-risk">${badge(p.risk)}</span><span class="facility-name">${esc(p.facility)}</span><span class="medicine-name">${esc(p.medicine)}</span></td><td><strong class="cover-number ${p.risk==='high'?'red':p.risk==='medium'?'amber':''}">${p.cover==null?'Unknown':num(p.cover,1)+' <small>days</small>'}</strong><span class="cover-target">${p.cover==null?'No positive consumption basis':`${p.safety_days}-day target · ${num(p.cover/p.safety_days*100,0)}% achieved`}</span><div class="stock-units">${p.stock==null?'Stock unavailable':num(p.stock)+' units'}${p.quality==='blocked'?' · prior valid record':''}</div></td><td class="prediction-column"><strong>${p.probability==null?'Not assessed':pct(p.probability,1)}</strong><span class="cover-target">${p.probability==null?'No reliable ML basis':state.window+'-day estimate'}</span></td><td class="quality-column">${badge(p.quality)}<span class="cover-target">${pct(p.reporting_completeness,0)} complete</span></td>${full?`<td class="evidence-column"><span class="evidence-type">${esc(p.causes[0].type)}</span>${esc(p.causes[0].label)}</td>`:''}<td><button class="table-action" data-action="detail" data-id="${p.finding_id}" aria-label="Investigate ${esc(p.facility)} — ${esc(p.medicine)}">↗</button></td></tr>`).join('')}</tbody></table></div>`;
}

function overview() {
 const d=state.data, q=d.quality, risks=d.pairs.filter(p=>p.risk==='high'), p=risks[0], plans=d.planner.recommendations;
 const medicineCounts = [...new Set(d.pairs.map(p=>p.medicine))].map(m=>({name:m,count:d.pairs.filter(p=>p.medicine===m&&p.risk==='high').length})).filter(m=>m.count>0).sort((a,b)=>b.count-a.count).slice(0,5);

 return heading('overview')+`<div class="ai-workflow"><span><b>01</b> Validated evidence</span><i>›</i><span class="active"><b>02</b> Risk forecast & explanation</span><i>›</i><span><b>03</b> Safe transfer options</span><i>›</i><button data-action="copilot"><b>04</b> Draft the supply brief</button><i>›</i><span><b>05</b> Human review</span></div><div class="kpi-strip">${kpi('High-risk stock signals',d.counts.high,'pairs',`Immediate review required · target 0`, 'high-risks','red','risk')}${kpi('Weekly reporting completeness',num(q.completeness*100,1),'%',`95% target · ${num(q.completeness/.95*100,1)}% achievement`,'quality',q.completeness>=.95?'':'amber','report')}${kpi('Feasible redistribution options',plans.length,'proposals',`${plans.filter(r=>r.status!=='pending').length} reviewed · ${plans.length?pct(plans.filter(r=>r.status!=='pending').length/plans.length,0):'N/A'} of 100% review target`,'planner','','transfer')}${kpi('Evidence requiring attention',d.counts.not_assessed,'pairs',`Not assessed · excluded from transfer proposals`,'weak-evidence','amber','quality')}</div>
 <div class="overview-grid"><section><div class="section-heading"><h2>Priority signals<span class="section-sub">${state.window}-DAY HORIZON</span></h2><a class="text-link" href="#risks">Explore all signals ↗</a></div>${riskTable(risks.slice(0,6))}<div class="table-caption"><span>${Math.min(risks.length,6)} of ${d.counts.high} high-risk signals · ranked by predicted risk, then stock cover</span><a class="text-link" href="#risks">View evidence →</a></div></section>
 <aside class="brief-aside"><div><div class="section-overline">THE DECISION DESK</div><h2>Where to focus<br>your next review.</h2>${p?`<div class="brief-flag"><span class="tiny-square" style="background:currentColor"></span> IMMEDIATE ATTENTION</div><h3>${esc(p.facility)}<br><em>${esc(p.medicine)}</em></h3><p>${p.delivery_delay?`An open delivery is ${p.delivery_delay} days overdue.`:'Usable stock is below the safety threshold.'} ${p.consumption_trend>.15?`Recent consumption is ${pct(p.consumption_trend,0)} above the observed average.`:''}</p>`:`<p>No high-risk pairs in this horizon. Review medium-risk and unassessed evidence before closing the briefing.</p>`}</div><div class="brief-body">${p?`<div class="brief-evidence"><div><strong>${num(p.cover,1)} <small>days</small></strong><span class="label">${p.safety_days}-day safety target<br>${num(p.cover/p.safety_days*100)}% achievement</span></div><div><strong>${num(p.stock)}</strong><span class="label">usable units<br>Reported evidence</span></div></div><button class="button" data-action="detail" data-id="${p.finding_id}">Review the evidence ${icon('arrow',15)}</button>`:''}<div class="brief-note"><p>${plans.length} redistribution proposals pass the deterministic constraints. Donor safety stock is preserved across the entire plan.</p><a class="text-link" href="#planner">Open redistribution planner →</a></div></div></aside></div>
 <div class="lower-grid"><section><div class="section-overline">DISTRICT PATTERN</div><div class="section-heading"><h2>Medicines under pressure.</h2><span class="subtle-caption">HIGH-RISK FACILITIES</span></div><div class="medicine-bars" role="img" aria-label="${esc(medicineCounts.map(m=>m.name+': '+m.count+' high-risk facilities').join('; '))}">${medicineCounts.length?medicineCounts.map(m=>`<div class="bar-row"><span>${esc(m.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${m.count/10*100}%"></div></div><span class="bar-total">${m.count} / 10</span></div>`).join(''):'<p class="muted">No high-risk medicines in this horizon.</p>'}</div><p class="subtle-caption">Actual high-risk facility counts out of 10 facilities per medicine. Unassessed pairs remain outside these counts.</p></section>
 <section class="editorial-panel"><div class="panel-head"><h3>The review queue.</h3><small>${state.window}-DAY HORIZON</small></div><p class="subtle-caption">Stock signals, feasible options and evidence still requiring attention.</p><div class="mini-metrics"><div class="mini-metric"><strong>${risks.length}</strong><span>high-risk pairs</span></div><div class="mini-metric"><strong>${plans.filter(r=>r.status==='pending').length}</strong><span>proposals awaiting review</span></div><div class="mini-metric"><strong>${q.blocked_pairs}</strong><span>pairs with evidence gaps</span></div></div><a class="text-link" href="#report">Read the complete supply brief →</a></section></div>
 <div class="note-band warning">${icon('quality',18)}<p><strong>The evidence gap is also a priority.</strong> ${q.blocked_pairs} pairs have limited or blocked source evidence. A missing recommendation does not mean adequate stock.</p><button class="text-link" data-action="weak-evidence">Inspect quality gaps ↗</button></div>`;
}

function filterOptions(field,label,items) { return `<div class="filter"><label for="filter-${field}">${label}</label><select id="filter-${field}" data-filter="${field}"><option value="">All ${label.toLowerCase()}</option>${items.map(([v,t])=>`<option value="${esc(v)}" ${state.filters[field]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`; }
function filteredPairs() { const f=state.filters;return state.data.pairs.filter(p=>(!f.facility||p.facility_id===f.facility)&&(!f.medicine||p.medicine_id===f.medicine)&&(!f.risk||p.risk===f.risk)&&(!f.quality||p.quality===f.quality)&&(!f.search||`${p.facility} ${p.medicine}`.toLowerCase().includes(f.search.toLowerCase()))); }
function risksPage() {
 const facilities=[...new Map(state.data.pairs.map(p=>[p.facility_id,p.facility])).entries()],medicines=[...new Map(state.data.pairs.map(p=>[p.medicine_id,p.medicine])).entries()];
 const filtered=filteredPairs(),active=Object.entries(state.filters).filter(([,v])=>v);
 return heading('risks')+`<div class="filters">${filterOptions('facility','Facilities',facilities)}${filterOptions('medicine','Medicines',medicines)}${filterOptions('risk','Risk levels',['high','medium','low','not_assessed'].map(x=>[x,labels[x]]))}${filterOptions('quality','Evidence quality',['strong','acceptable','limited','blocked'].map(x=>[x,labels[x]]))}<button class="text-link filter-clear" data-action="clear-filters">Clear filters</button></div><div class="button-row"><button class="button secondary compact" data-action="copilot">Summarise current supply risks</button></div><div class="result-summary top-gap"><span>${filtered.length} matching ${filtered.length===1?'pair':'pairs'}</span>${active.map(([k,v])=>`<span class="active-chip">${esc(k==='facility'?new Map(facilities).get(v):k==='medicine'?new Map(medicines).get(v):labels[v]||v)}<button data-action="remove-filter" data-filter="${k}" aria-label="Remove ${esc(k)} filter">×</button></span>`).join('')}</div>${riskTable(filtered,true)}<div class="note-band">${icon('risk',18)}<p><strong>Read actual evidence first.</strong> Risk bands preserve a conservative stock-cover baseline. Model probabilities, where available, are advisory. Unassessed results require evidence recovery.</p><button class="text-link" data-action="method">Method & model evidence ↗</button></div>`;
}

function plannerPage() {
 const plans=state.data.planner, filtered=plans.recommendations.filter(r=>state.plannerTab==='all'||state.plannerTab==='pending'&&r.status==='pending'||state.plannerTab==='reviewed'&&r.status!=='pending');
 return heading('planner')+`<div class="note-band">${icon('transfer',19)}<p><strong>A review decision does not move stock.</strong> All proposed quantities preserve donor safety stock, valid packs, shelf life and evidence requirements. Transport and storage still need human confirmation.</p></div><div class="button-row"><button class="button secondary compact" data-action="assist-plan">Explain the proposed plan</button></div><div class="tab-group" role="group" aria-label="Recommendation status">${[['all','All proposals',plans.recommendations.length],['pending','Pending review',plans.recommendations.filter(r=>r.status==='pending').length],['reviewed','Reviewed',plans.recommendations.filter(r=>r.status!=='pending').length],['withheld','Withheld',plans.withheld.length]].map(([v,t,n])=>`<button data-action="planner-tab" data-tab="${v}" class="${state.plannerTab===v?'active':''}" aria-pressed="${state.plannerTab===v}">${t} <span class="section-sub">${n}</span></button>`).join('')}</div>${state.plannerTab==='withheld'?`<div class="section-heading"><h2>Why proposals are withheld.</h2></div>${plans.withheld.map(w=>`<div class="withheld-row"><div><strong>${esc(w.facility)}</strong><br><span class="muted">${esc(w.medicine)}</span></div><div><p>${esc(w.reason)}</p><button class="text-link" data-action="detail" data-id="${w.finding_id}">Inspect the source evidence ↗</button></div></div>`).join('')}`:filtered.length?`<div class="planner-header"><span class="section-overline">FEASIBLE UNDER CONFIGURED CONSTRAINTS</span><span class="subtle-caption">One donor per recipient · shared donor reservations</span></div>${filtered.map((r,i)=>`<article class="transfer-row"><div class="transfer-index">${String(i+1).padStart(2,'0')}</div><div class="transfer-title"><strong>${esc(r.medicine)}</strong><span>${r.near_expiry?'Near-expiry stock opportunity':'Supply continuity'} · ${num(r.distance_km,1)} km proxy</span></div><div class="transfer-route"><div><div class="route-label">Potential donor</div><div class="route-name">${esc(r.donor)}</div><div class="route-cover">${num(r.donor_before,1)} → ${num(r.reviewed_donor_after??r.donor_after,1)} <small>days</small></div></div><span class="muted">→</span><div><div class="route-label">Recipient</div><div class="route-name">${esc(r.recipient)}</div><div class="route-cover">${num(r.recipient_before,1)} → ${num(r.reviewed_recipient_after??r.recipient_after,1)} <small>days</small></div></div></div><div class="transfer-quantity">${num(r.reviewed_quantity??r.quantity)}<small>units · ${num((r.reviewed_quantity??r.quantity)/r.pack_size)} packs</small></div><div class="transfer-action">${badge(r.status)}<button class="button secondary compact" data-action="review" data-id="${r.recommendation_id}">${r.status==='pending'?'Review proposal':'View review'} ↗</button><button class="text-link" data-action="assist-plan" data-id="${r.recommendation_id}">Explain this option</button></div></article>`).join('')}`:`<div class="empty"><h2>No proposals in this view.</h2><p>${state.plannerTab==='reviewed'?'Recorded decisions will appear here after a proposal has been reviewed.':'Check the withheld queue for unmet constraints. Absence of a proposal does not indicate absence of risk.'}</p></div>`}`;
}

function qualityPage() {
 const q=state.data.quality;
 return heading('quality')+`<div class="note-band ${q.rejected_count?'warning':''}">${icon('quality',19)}<p><strong>${num(q.accepted)} accepted rows · ${q.rejected_count} rejected.</strong> Rejected records are quarantined. Critical failures override aggregate scores, and weak-evidence transfers remain withheld.</p><a class="text-link" href="/api/data/rejections.csv" download>Download rejection log ↓</a></div><button class="button secondary compact" data-action="assist-quality">Summarise reporting corrections</button><div class="dimension-grid">${[['Completeness',q.completeness,.95],['Timeliness',q.timeliness,.95],['Validity',q.validity,1],['Consistency',q.consistency,1],['Uniqueness',q.uniqueness,1]].map(([label,v,t])=>`<div class="dimension"><label>${label}</label><strong class="${v>=t?'':v/t>=.85?'amber':'red'}">${pct(v,1)}</strong><small>${pct(t,0)} target · ${pct(v/t,1)} achievement</small></div>`).join('')}</div><div class="quality-layout"><section><div class="section-heading"><h2>Facility reporting.</h2><span class="subtle-caption">LATEST 12 WEEKS</span></div><div class="table-scroll"><table class="risk-table"><thead><tr><th>Facility</th><th>Actual completeness</th><th>Evidence status</th><th>Withheld pairs</th></tr></thead><tbody>${q.facilities.map(f=>`<tr><td><span class="facility-name">${esc(f.facility)}</span><span class="medicine-name">${esc(f.location_type.replace('_',' '))}</span></td><td><strong>${pct(f.completeness,1)}</strong><span class="cover-target">95% target · ${pct(f.completeness/.95,1)} achievement</span></td><td>${badge(f.quality)}</td><td>${f.blocked_pairs}</td></tr>`).join('')}</tbody></table></div><p class="subtle-caption top-gap">Completeness: ${q.received_reports} validated weekly reports / ${q.expected_reports} expected. Timeliness uses expected reports as its denominator. Validity and uniqueness use all source rows; consistency uses inventory source rows.</p></section><aside><div class="section-overline">SOURCE ACCOUNTABILITY</div><h3>The trail behind the numbers.</h3><dl class="provenance-list"><div><dt>Import identifier</dt><dd>${esc(q.import_id)}</dd></div><div><dt>Validation policy</dt><dd>${esc(state.data.context.config_version)} · schema ${esc(state.data.context.schema_version)}</dd></div><div><dt>Imported (UTC)</dt><dd>${esc(new Date(state.data.context.created_at).toLocaleString('en-GB',{timeZone:'UTC'}))}</dd></div><div><dt>Content checksum · SHA-256</dt><dd>${esc(q.checksum)}</dd></div></dl><div class="top-gap">${q.sources.map(s=>`<div class="source-row"><div>${esc(s.filename)}<small>${esc(s.entity)}</small></div><span>${num(s.rows)} rows</span></div>`).join('')}</div><button class="text-link top-gap" data-action="import">Import a new CSV bundle ↗</button></aside></div><section class="top-gap"><div class="section-heading"><h2>Rejected source records.</h2><span class="subtle-caption">EXCLUDED FROM ANALYSIS</span></div>${q.rejected.length?`<div class="table-scroll"><table class="risk-table"><thead><tr><th>Source / row</th><th>Facility / medicine</th><th>Rule</th><th>Reason</th></tr></thead><tbody>${q.rejected.slice(0,100).map(r=>`<tr><td>${esc(r.entity)} · ${r.row}</td><td>${esc(r.facility_id)} / ${esc(r.medicine_id)}</td><td>${esc(r.rule)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table></div>${q.rejected.length>100?'<p class="subtle-caption">First 100 shown; download the complete rejection log above.</p>':''}`:'<p class="muted">No rejected records. Review reporting gaps separately.</p>'}</section>`;
}

const reportSections=['Executive Summary','Project Metadata & Governance Context','Activity Implementation Analysis','Workplan Analysis','Logframe Performance Analysis','Indicator Performance Analysis','Risk & Bottleneck Analysis','Issues Log Analysis','Budget & Resource Utilization','Data Quality Assessment','Dependency & Impact Analysis','Forecasting & Predictive Insights','Recommendations & Corrective Action Plan'];
function chosenFindings() {return state.data.pairs.filter(p=>state.draft.selected_findings===null||state.draft.selected_findings.includes(p.finding_id));}
function reportSidebar() {
 const candidates=state.data.pairs.filter(p=>p.risk==='high'||p.risk==='medium');
 return `<aside class="report-sidebar"><div class="section-overline">REPORT BUILDER</div><h3>Make it accountable.</h3><p>Use the validated findings, add management context and assign the follow-through.</p><div class="field"><label for="narrativeMode">Narrative approach</label><select id="narrativeMode" data-draft="narrative_mode"><option value="gemini" ${state.draft.narrative_mode==='gemini'?'selected':''}>Assisted operational draft</option><option value="deterministic" ${state.draft.narrative_mode==='deterministic'?'selected':''}>Standard operational brief</option></select><p class="report-helper">${state.data.context.llm_enabled?'Drafting support is available.':'Standard evidence-based drafting is available.'} Drafting uses approved summary facts; every figure remains tied to its source.</p><button class="text-link" data-action="generate-narrative">Draft the operational summary</button></div><div class="field"><label for="preparedBy">Prepared by</label><input id="preparedBy" data-draft="prepared_by" value="${esc(state.draft.prepared_by)}" maxlength="100" required></div><div class="field"><label for="managementNote">Management note</label><textarea id="managementNote" data-draft="management_note" placeholder="Add the context a director needs…" maxlength="3000">${esc(state.draft.management_note)}</textarea></div><div class="field"><span class="field-label" id="findingLabel">Include stock findings</span><div class="findings-selector" role="group" aria-labelledby="findingLabel"><label class="check-row"><input type="checkbox" id="allFindings" data-all-findings ${state.draft.selected_findings===null?'checked':''}><span>All current findings <small>Includes unassessed evidence and limitations</small></span></label>${candidates.map(p=>`<label class="check-row"><input type="checkbox" data-finding="${p.finding_id}" ${state.draft.selected_findings===null||state.draft.selected_findings.includes(p.finding_id)?'checked':''}><span>${esc(p.facility)}<small>${esc(p.medicine)}</small></span></label>`).join('')}</div></div><div class="form-error" data-error hidden tabindex="-1"></div><button class="button" data-action="full-report">Preview full report ↗</button><button class="button secondary" data-action="download-report">Export HTML report ↓</button><button class="button secondary" data-action="save-draft">Save working draft</button><p class="report-helper">Review the complete supply position, decisions and owners. Export the brief or a separate escalation email.</p><div class="data-type-label">${state.draft.narrative_mode==='gemini'?'SOURCE-CHECKED · REVIEW REQUIRED':'SOURCE-BASED BRIEF'}</div></aside>`;
}
function briefingPreview() {
 const d=state.data,high=chosenFindings().filter(p=>p.risk==='high');
 return `<article class="report-sheet"><div class="report-brand">MEDFLOW AFRICA <span class="muted">/ SUPPLY POSITION</span></div><div class="eyebrow top-gap">DISTRICT SUPPLY REVIEW</div><h2>Evidence into action.</h2><p class="muted">District medicine-supply brief<br>${esc(d.context.district)} · ${esc(dateLabel(d.context.cutoff))}</p><div class="report-summary-grid"><div><strong class="red">${high.length}</strong><small>PRIORITY STOCK RISKS</small></div><div><strong>${d.planner.recommendations.length}</strong><small>FEASIBLE PROPOSALS</small></div><div><strong>${d.quality.blocked_pairs}</strong><small>PAIRS WITH EVIDENCE GAPS</small></div></div>${state.aiDraft?`<div class="note-band"><div><span class="evidence-type">${esc(state.aiDraft.label)}</span><p>${esc(state.aiDraft.reason)}</p>${(state.aiDraft.sections?.executive_summary||[]).map(p=>`<p>${esc(p.text)}</p>`).join('')}</div></div>`:''}<h3><span class="report-section-num">01 / EXECUTIVE SUMMARY</span>Restore cover. Close the evidence gaps.</h3><p class="report-lead">${high.length} high-risk pairs in the selected findings require prompt review. The next decision is to confirm stock balances and delivery dates, then review safe redistribution.</p><p>${d.quality.blocked_pairs} facility–medicine pairs have insufficient evidence for redistribution. Reconcile missing reports and rejected balances in Data quality before reviewing affected transfer options.</p>${state.draft.management_note?`<div class="note-band"><p><strong>Management note:</strong> ${esc(state.draft.management_note)}</p></div>`:''}${high[0]?`<div class="boxed-risk"><strong>PRIORITY RISK · ${esc(high[0].facility)}</strong><p>${esc(high[0].medicine)} has ${num(high[0].cover,1)} days of stock cover against ${high[0].safety_days} days required — ${num(high[0].cover/high[0].safety_days*100,1)}% achievement. ${high[0].delivery_delay} days of delivery delay are recorded. District pharmacist and logistics lead to validate the recovery action.</p></div>`:''}<h3><span class="report-section-num">06 / INDICATOR PERFORMANCE ANALYSIS</span>The current operating position.</h3><table class="report-mini-table"><thead><tr><th>Indicator</th><th>Actual</th><th>vs target</th><th>Status</th></tr></thead><tbody>${d.programme.indicators.filter(i=>['IND-01','IND-02','IND-05'].includes(i.id)).map(i=>`<tr><td>${esc(i.name)}</td><td>${num(i.actual,i.unit==='%'?1:0)} ${esc(i.unit)}</td><td>${num(i.target)} · ${i.achievement==null?'N/A':num(i.achievement,1)+'% achieved'}</td><td>${badge(i.status)}</td></tr>`).join('')}</tbody></table><div class="report-toc">${reportSections.map((s,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b>${s}</div>`).join('')}</div><p class="subtle-caption">This is the executive preview. “Preview full report” opens all 13 sections, including the workplan, logframe, resource ledger and action register.</p></article>`;
}
function programmePreview() {
 const p=state.data.programme,t=p.budget_totals;
 return `<article class="report-sheet"><div class="report-brand">DISTRICT READINESS / LOGISTICS RESOURCES</div><h2>Behind the results.</h2><p>These are example project-planning records. Workplan and budget figures are not calculated from inventory imports. Replace the planning ledger with approved project records before using it for programme reporting.</p><h3>Supply-readiness tasks.</h3><div class="timeline">${p.activities.map(a=>`<div class="timeline-row"><span class="timeline-date">${esc(a.id)}</span><div><strong>${esc(a.name)}</strong><small>${a.actual} / ${a.planned} ${esc(a.unit)} · ${num(a.actual/a.planned*100)}% achievement<br>${esc(a.owner)} · due ${esc(a.due)}</small></div>${badge(a.status)}</div>`).join('')}</div><h3>Resources in use.</h3><p class="report-lead">US$${num(t.spent)} spent — ${num(t.spent/t.planned_to_date*100,1)}% of the US$${num(t.planned_to_date)} phased plan.</p><table class="report-mini-table"><thead><tr><th>Budget line</th><th>Actual spent</th><th>vs planned to date</th></tr></thead><tbody>${p.budget.map(b=>`<tr><td>${esc(b.line)}</td><td>$${num(b.spent)}</td><td>$${num(b.planned_to_date)} · ${num(b.spent/b.planned_to_date*100,1)}%</td></tr>`).join('')}</tbody></table><p class="subtle-caption top-gap">$${num(t.allocated)} total allocation · $${num(t.committed)} commitments · $${num(t.allocated-t.spent-t.committed)} uncommitted. Currency: USD. Expenditure is not a proxy for results.</p><h3>Issues to resolve.</h3>${p.issues.filter(i=>i.status!=='closed').map(i=>`<div class="boxed-risk"><strong>${esc(i.id)} · ${esc(i.issue)}</strong><p>${esc(i.action)}<br><strong>${esc(i.owner)}</strong> · due ${esc(i.due)} · ${esc(i.status.replace('_',' '))}</p></div>`).join('')}</article>`;
}
function actionsPreview() {
 const candidates=chosenFindings().filter(p=>p.risk==='high'),actions=state.draft.actions;
 return `<article class="report-sheet"><div class="report-brand">CORRECTIVE ACTION REGISTER</div><h2>Name the next step.</h2><p>Assign a concrete action, an owner and a deadline. Changes are saved to the working draft and included in the report export.</p><div class="action-list">${candidates.map(p=>{const a=actions.find(a=>a.finding_id===p.finding_id)||{};return `<div class="action-item" data-action-row="${p.finding_id}"><strong>${esc(p.facility)} · ${esc(p.medicine)}</strong><div class="field top-gap"><label for="act-${p.finding_id}">Corrective action</label><textarea id="act-${p.finding_id}" data-action-field="action" maxlength="600" placeholder="Validate stock balance, confirm delivery and review a safe transfer…">${esc(a.action||'')}</textarea></div><div class="action-grid"><div><label for="owner-${p.finding_id}">Owner</label><input id="owner-${p.finding_id}" data-action-field="owner" value="${esc(a.owner||'')}" placeholder="District pharmacist" maxlength="80"></div><div><label for="due-${p.finding_id}">Due date</label><input id="due-${p.finding_id}" type="date" data-action-field="due_date" value="${esc(a.due_date||'')}"></div><div class="status-field"><label for="status-${p.finding_id}">Status</label><select id="status-${p.finding_id}" data-action-field="status">${['open','in_progress','closed'].map(x=>`<option value="${x}" ${(a.status||'open')===x?'selected':''}>${x.replace('_',' ')}</option>`).join('')}</select></div></div></div>`;}).join('')}</div>${!candidates.length?'<p>No high-risk findings selected. Include findings in the builder to assign actions.</p>':''}<div class="button-row top-gap"><button class="button" data-action="save-draft">Save action register</button><button class="button secondary" data-action="suggest-actions">Populate suggested owners & dates</button></div><p class="subtle-caption top-gap">Suggested assignments are synthetic planning defaults. Saving records the draft; it does not complete the operational action.</p><div class="form-error" data-error hidden tabindex="-1"></div></article>`;
}
function reportPage() {
 return heading('report')+`<div class="report-layout">${reportSidebar()}<section><div class="report-tabs" role="group" aria-label="Report workspace">${[['briefing','Executive preview'],['programme','Readiness & resources'],['actions','Action register'],['email','Escalation email']].map(([v,t])=>`<button data-action="report-tab" data-tab="${v}" class="${state.reportTab===v?'active':''}" aria-pressed="${state.reportTab===v}">${t}</button>`).join('')}</div>${state.reportTab==='programme'?programmePreview():state.reportTab==='actions'?actionsPreview():state.reportTab==='email'?emailPreview():briefingPreview()}</section></div>`;
}
function emailPreview() {return `<article class="report-sheet"><div class="report-brand">SEPARATE ESCALATION DRAFT / HUMAN REVIEW</div><h2>A clear request<br>for action.</h2><p>Exact stock values, target variances, contributing causes, potential impact and recommended actions are drawn from the selected findings.</p><div class="button-row"><button class="button" data-action="generate-email">${state.email?'Regenerate draft':'Generate escalation draft'}</button>${state.email?'<button class="button secondary" data-action="download-email">Download .eml ↓</button><button class="button secondary" data-action="copy-email">Copy email</button>':''}</div>${state.email?`<div class="email-subject"><span class="evidence-type">SUBJECT</span>${esc(state.email.subject)}</div><div class="email-body">${esc(state.email.body)}</div>`:'<div class="note-band"><p>The draft will appear here. No email is sent from this application.</p></div>'}</article>`;}

function decorateIcons(root=document) {
 $$('button,a',root).forEach(el=>{
  if(!el.textContent.includes('↗'))return;
  const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))if(node.textContent.includes('↗'))node.textContent=node.textContent.replaceAll('↗','');
  const a=el.dataset.action;const kind=a==='import'||a==='load-demo'?'upload':a==='detail'?'search':a==='method'?'quality':a==='audit'?'clock':a==='review'||a==='planner'?'transfer':a==='print-report'?'print':a==='download-report'?'download':a==='full-report'?'report':el.getAttribute('href')==='#risks'?'search':el.getAttribute('href')==='#planner'?'transfer':'report';
  if(!el.querySelector('svg'))el.insertAdjacentHTML('beforeend',icon(kind,14));
 });
}

function render() {
 if(!state.data)return;
 state.page=location.hash.slice(1)||'overview';if(!pageDetails[state.page])state.page='overview';
 $$('.nav-links a').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);a.setAttribute('aria-current',a.dataset.page===state.page?'page':'false');});
 $('#main').innerHTML=({overview,risks:risksPage,planner:plannerPage,quality:qualityPage,report:reportPage,ai:aiPage}[state.page])();
 decorateIcons();
 document.title=`${pageDetails[state.page][1].replace(/\.$/,'')} — MedFlow Africa`;
 announce(`${pageDetails[state.page][1]} ${state.page==='risks'?filteredPairs().length+' matching findings.':''}`);
}

function openModal(content,wide=false){const dialog=$('#modal');$('#modalContent').innerHTML=content;dialog.classList.toggle('wide',wide);decorateIcons(dialog);if(!dialog.open)dialog.showModal();}
function closeDialogs(){$$('dialog[open]').forEach(d=>d.close());}
function dialogHead(overline,title,detail=false) {return `<div class="dialog-head"><div><div class="eyebrow">${overline}</div><h2 id="${detail?'detailTitle':'modalTitle'}">${title}</h2></div><button class="close-button" data-action="close-dialog" aria-label="Close dialog">×</button></div>`;}

function trendChart(history,key,label,color) {
 const width=670,height=145,left=45,right=12,top=12,bottom=27,max=Math.max(...history.map(h=>h[key]??0),1)*1.12;
 const x=i=>left+i*(width-left-right)/(history.length-1),y=v=>height-bottom-v/max*(height-top-bottom);
 const segments=[];let current=[];history.forEach((h,i)=>{if(h[key]==null){if(current.length)segments.push(current);current=[];}else current.push([x(i),y(h[key])]);});if(current.length)segments.push(current);
 return `<div class="chart-label">${label} · units</div><svg class="trend-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(label)} over 12 weeks. Missing reports are shown as gaps. A detailed table follows.">${[0,.5,1].map(f=>`<line x1="${left}" y1="${y(max*f)}" x2="${width-right}" y2="${y(max*f)}" stroke="#d8d5cc" stroke-width=".8"/><text x="${left-8}" y="${y(max*f)+3}" text-anchor="end">${num(max*f)}</text>`).join('')}${segments.map(points=>`<polyline points="${points.map(a=>a.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>${points.map(([px,py])=>`<circle cx="${px}" cy="${py}" r="2.5" fill="${color}"/>`).join('')}`).join('')}${history.map((h,i)=>i%3===0||i===history.length-1?`<text x="${x(i)}" y="${height-6}" text-anchor="${i===history.length-1?'end':i===0?'start':'middle'}">${esc(new Date(h.date+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short'}))}</text>`:'').join('')}</svg>`;
}

function showDetail(id) {
 const p=state.data.pairs.find(p=>p.finding_id===id);if(!p)return;
 const c=state.data.context,proposal=state.data.planner.recommendations.find(r=>r.finding_id===id);
 $('#detailContent').innerHTML=dialogHead(`${esc(p.finding_id)} · ${state.window}-DAY HORIZON`,esc(p.facility),true)+`<div class="dialog-body"><div class="drawer-subtitle">${esc(p.medicine)}</div><div class="detail-status top-gap">${badge(p.risk)}${badge(p.quality)}<span class="subtle-caption">Evidence at ${esc(p.last_report||'unknown date')}</span></div>${p.warnings.map(w=>`<div class="note-band warning"><p>${esc(w)}</p></div>`).join('')}<div class="detail-metrics"><div class="detail-metric"><span class="label">Actual usable stock</span><strong>${num(p.stock)}</strong><small>Reported units${p.quality==='blocked'?' · prior valid evidence':''}<br>Reorder point: ${num(p.reorder_point)} units</small></div><div class="detail-metric"><span class="label">Actual stock cover</span><strong class="${p.risk==='high'?'red':''}">${num(p.cover,1)}</strong><small>${p.safety_days}-day target · ${p.cover==null?'N/A':pct(p.cover/p.safety_days,1)} achievement<br>${p.cover==null?'No positive demand basis':'Calculated days remaining'}</small></div><div class="detail-metric"><span class="label">Daily consumption</span><strong>${num(p.adc,1)}</strong><small>Calculated units / day<br>${p.observed_days} observed days in recent 4 weeks</small></div></div>${p.prediction_factors?.length?`<div class="detail-section"><div class="section-overline">FORECAST MODEL · ${esc(p.model)}</div><h3>What drove the prediction.</h3><div class="model-estimate"><strong>${pct(p.probability,1)}</strong><span>estimated ${state.window}-day stock-out probability<br>Evidence confidence: ${esc(p.quality)} · synthetic model</span></div>${p.prediction_factors.map((f,i)=>`<div class="factor"><span class="factor-index">${i+1}</span><div><span class="evidence-type">${esc(f.direction)} · model contribution ${f.contribution>0?'+':''}${num(f.contribution,3)}</span><p><strong>${esc(f.feature.replaceAll('_',' '))}</strong> · actual feature value ${num(f.value,2)}</p></div></div>`).join('')}<p class="subtle-caption top-gap">${esc(p.explanation_method)}. These contributions describe model behaviour; they do not establish operational causality. A conservative stock-cover alert cannot be suppressed.</p></div>`:''}<div class="detail-section"><h3>Operational evidence behind the signal.</h3>${p.factors.map((f,i)=>`<div class="factor"><span class="factor-index">${i+1}</span><div><span class="evidence-type">${esc(f.type)}</span><p>${esc(f.text)}</p></div></div>`).join('')}</div><div class="detail-section"><h3>The stock and consumption record.</h3>${trendChart(p.history,'stock','Closing stock','#344d68')}${trendChart(p.history,'dispensed','Weekly consumption','#8a7966')}<p class="subtle-caption">Separate scales preserve the units of each series. Missing periods appear as gaps. Deliveries and stock-out days are included in the table.</p><details class="chart-alt"><summary>View the underlying weekly data</summary><div class="table-scroll"><table class="report-mini-table"><thead><tr><th>Week ending</th><th>Stock</th><th>Dispensed</th><th>Received</th><th>Stock-out days</th></tr></thead><tbody>${p.history.map(h=>`<tr><td>${h.date}</td><td>${num(h.stock)}</td><td>${num(h.dispensed)}</td><td>${num(h.received)}</td><td>${num(h.stockout_days)}</td></tr>`).join('')}</tbody></table></div></details></div><div class="detail-section"><h3>Operational interpretation.</h3>${p.causes.map(c=>`<div class="factor"><div><span class="evidence-type">${esc(c.type)}</span><strong>${esc(c.label)}</strong><p>${esc(c.detail)}</p></div></div>`).join('')}<div class="note-band"><p><strong>${p.probability==null?'Deterministic baseline':`Predicted ML risk: ${pct(p.probability,1)}`}.</strong> ${p.probability==null?`Cover is ${p.baseline_at_risk?'below':'not below'} the ${state.window}-day horizon${p.cover==null?' (cover unknown)':''}. No calibrated probability is asserted.`:'Conservative stock-cover alerts are retained even if the model estimates lower risk.'}</p></div></div><details class="chart-alt"><summary>Analysis provenance</summary><dl class="provenance-list"><div><dt>Dataset / import</dt><dd>${esc(c.data_version)} · ${esc(c.import_id)}</dd></div><div><dt>Model / policy</dt><dd>${esc(p.model)} · ${esc(c.config_version)}</dd></div><div><dt>Data status</dt><dd>${c.synthetic?'Sample records':'User-attested anonymised operational data'}</dd></div><div><dt>Open orders</dt><dd>${num(p.open_order_units)} units outstanding · ${p.delivery_delay} days ongoing delay</dd></div></dl></details><div class="button-row top-gap"><button class="button secondary" data-action="assist-risk" data-id="${p.finding_id}">Explain this risk ${icon('search',14)}</button>${proposal?`<button class="button" data-action="review" data-id="${proposal.recommendation_id}">Review redistribution proposal ↗</button>`:'<button class="button secondary" data-action="planner">View redistribution constraints ↗</button>'}<button class="button secondary" data-action="add-report" data-id="${p.finding_id}">Include in action report</button></div></div>`;
 decorateIcons($('#detailDialog')); $('#detailDialog').showModal();
}

function showReview(id) {
 const r=state.data.planner.recommendations.find(r=>r.recommendation_id===id);if(!r)return;
 if($('#detailDialog').open)$('#detailDialog').close();
 openModal(dialogHead(`${esc(r.recommendation_id)} · VERSION ${r.version}`,'Review the proposal.')+`<form id="reviewForm" data-id="${r.recommendation_id}"><div class="dialog-body"><span class="evidence-type">${esc(r.medicine)} · ${num(r.quantity)} proposed units / ${num(r.quantity/r.pack_size)} packs</span>${r.review?`<div class="review-history"><strong>${esc(labels[r.status])} · version ${r.version}</strong><p>${esc(r.review.reviewer)}: ${esc(r.review.note)}</p><p class="subtle-caption">${esc(r.review.reviewed_at)} · original proposal remains unchanged</p><button type="button" class="text-link" data-action="audit" data-id="${r.review.audit_id}">View audit event #${r.review.audit_id} ↗</button></div>`:''}<div class="compare-grid"><div class="compare-block"><div class="route-label">Donor facility</div><h3>${esc(r.donor)}</h3><div class="compare-values">${num(r.donor_before,1)} <span>→</span> ${num(r.reviewed_donor_after??r.donor_after,1)}</div><small>Days of stock cover before → after<br>${r.safety_days}-day safety target · ${num((r.reviewed_donor_after??r.donor_after)/r.safety_days*100,0)}% achievement after proposal<br>Includes earlier reserved proposals</small></div><div class="compare-block"><div class="route-label">Recipient facility</div><h3>${esc(r.recipient)}</h3><div class="compare-values">${num(r.recipient_before,1)} <span>→</span> ${num(r.reviewed_recipient_after??r.recipient_after,1)}</div><small>Days of stock cover before → after<br>30-day target · ${num((r.reviewed_recipient_after??r.recipient_after)/30*100,0)}% achievement after proposal<br>${num(r.distance_km,1)} km straight-line proxy</small></div></div><p>${esc(r.reason)}</p><ul class="constraint-list">${r.constraints.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="subtle-caption">Expiry ${r.expiry_date} · ${r.shelf_life_days} days remaining. ${r.warnings.map(esc).join(' ')}</p><fieldset style="border:0;padding:0;margin:24px 0 0"><legend class="field-label">Record a review decision</legend><div class="review-choices">${[['accepted','Accept'],['edited','Edit quantity'],['rejected','Reject']].map(([v,t])=>`<label class="review-choice"><input type="radio" name="decision" value="${v}" required><span>${t}</span></label>`).join('')}</div></fieldset><div class="field" id="editQuantityField" hidden><label for="reviewQuantity">Reviewed quantity (units)</label><input id="reviewQuantity" type="number" name="quantity" min="${r.pack_size}" max="${r.max_quantity}" step="${r.pack_size}" value="${r.reviewed_quantity??r.quantity}"><div class="review-note">${r.pack_size}-unit packs · maximum reserved safe quantity ${num(r.max_quantity)} units.</div></div><div class="field"><label for="reviewer">Reviewer name or role</label><input id="reviewer" name="reviewer" minlength="2" maxlength="80" placeholder="District pharmacist" required></div><div class="field"><label for="reviewNote">Review rationale</label><textarea id="reviewNote" name="note" minlength="5" maxlength="1000" placeholder="Record the evidence checked and the reason for your decision." required></textarea></div><label class="check-row"><input type="checkbox" name="acknowledged" required><span>I understand that this records a review decision and does not move stock.</span></label><div class="form-error" data-error hidden tabindex="-1"></div></div><div class="dialog-footer"><button type="button" class="button secondary" data-action="close-dialog">Cancel</button><button type="submit" class="button">Record review decision →</button></div></form>`);
}

function showImport() {
 openModal(dialogHead('DATA INTAKE · SCHEMA 1.0.0','Start with the evidence.')+`<div class="dialog-body"><p>Use the bundled records, or import four UTF-8 CSV files. Invalid rows are quarantined before analysis. Imports with missing critical reference data cannot become the active dataset.</p><button class="button" data-action="load-demo">Load bundled demonstration ↗</button><p class="subtle-caption top-gap">10 fictional facilities · 10 medicines · 60 weekly periods · fixed seed 42. Loading again preserves existing review history for the same dataset.</p><details class="chart-alt"><summary>Download the example CSV schemas</summary>${['facilities','medicines','inventory','orders'].map(e=>`<div class="download-row"><span>${e}.csv</span><a class="text-link" href="/api/data/demo/${e}.csv" download>Download ↓</a></div>`).join('')}</details><div class="rule-section"><span class="section-overline">OR UPLOAD A CSV BUNDLE</span><form id="importForm"><div class="upload-grid">${['facilities','medicines','inventory','orders'].map(e=>`<div class="field"><label for="upload-${e}">${e[0].toUpperCase()+e.slice(1)} CSV</label><input type="file" id="upload-${e}" name="${e}" accept=".csv,text/csv" required></div>`).join('')}</div><div class="field top-gap"><label for="uploadCutoff">Dataset reporting cut-off</label><input type="date" id="uploadCutoff" name="cutoff" value="${state.data?.context.cutoff||'2026-11-01'}" required></div><label class="check-row"><input type="checkbox" name="anonymised_confirmed" value="true" required><span>I confirm these are synthetic or anonymised operational records with no patient identifiers or personal clinical data.</span></label><p class="subtle-caption">8 MB per file. Programme workplan, logframe and budget records remain the sample dataset ledger.</p><div class="form-error" data-error hidden tabindex="-1"></div><button class="button secondary" type="submit">Validate & import bundle →</button></form></div></div>`);
}

async function showMethod() {
 openModal(dialogHead('ANALYTICAL TRANSPARENCY','Understand the method.')+`<div class="dialog-body"><p>Stock cover uses valid closing stock divided by observed average daily consumption. The four-week demand denominator excludes missing reports. A zero-consumption pair has unknown cover.</p><div class="note-band"><p>Risk estimates support human decisions. No transfer, order or procurement action is executed. All demonstration results are synthetic. Gemini is an optional drafting assistant; numeric calculations remain deterministic.</p></div><h3>Deterministic constraints.</h3><ul class="constraint-list"><li>Donor post-transfer cover remains at or above medicine-specific safety stock.</li><li>Shared donor stock is reserved across the complete proposal batch.</li><li>Quantities are rounded down to whole packs.</li><li>Recipient consumption must use the stock before expiry, after a 3-day transport buffer.</li><li>Fresh stock, expiry and minimum 85% reporting evidence are required.</li></ul><p>Baseline high risk: cover below the selected 7-, 14- or 30-day horizon. Medium: cover below the greater of horizon + 7 days and safety stock. Quality gates override classification to “Not assessed”. ML probabilities may raise a band, but never suppress a baseline alert.</p><h3>Predictive model evidence.</h3><button class="button secondary compact" data-action="monitor">Inspect model performance</button><div id="modelEvidence"><p>Loading the reproducible evaluation…</p></div><h3>Known limits.</h3><p>One fictional district, synthetic coordinates and no patient outcomes. Distances are straight-line proxies. Cold-chain and transport feasibility require manual confirmation. Imported stock is assumed usable as declared; expired and quarantined quantities must be removed before import. Missing data does not establish low need.</p><p>Each hosted browser workspace uses an unguessable HttpOnly cookie and isolated private storage. Keep this prototype behind Vercel deployment protection for operational use. Local storage uses SQLite; hosted snapshots use conditional private Blob writes. This is a portfolio prototype, not a production health system.</p><p>Data retention policy: 90 days; automatic hosted workspace deletion is not configured. Clear access to a workspace by clearing the browser cookie; storage removal requires an administrator. Reports retain a deterministic fallback. Gemini 3.8 Flash can sequence approved synthetic summary facts; raw uploads, reviewer notes and management notes are never sent. Missing keys, timeouts, quotas and unsupported outputs fall back safely.</p></div>`,true);
 try {const e=await api('/model/evaluation');if(!$('#modelEvidence'))return;if(e.status==='not_trained'){$('#modelEvidence').textContent=e.message;return;}const m=e.test?.model||{},b=e.test?.baseline||{};$('#modelEvidence').innerHTML=`<p>${esc(e.version)} · ${esc(e.promotion?.approved?'Approved for synthetic advisory scoring':'Evaluated; baseline retained')}<br>${esc(e.promotion?.reason||'')}<br>Time-based split with ${e.split?.purge_days||30}-day label purges. Test observations: ${num(e.test?.sample_count)}.</p><div class="model-grid">${[['Recall',m.recall],['Precision',m.precision],['PR-AUC',m.pr_auc],['Brier score',m.brier],['F1',m.f1],['Baseline recall',b.recall]].map(([label,v])=>`<div><strong>${num(v,3)}</strong><small>${label} · synthetic holdout</small></div>`).join('')}</div><details class="chart-alt"><summary>Subgroup results and evaluation details</summary><div class="table-scroll"><table class="report-mini-table"><thead><tr><th>Group</th><th>n</th><th>Recall</th><th>Precision</th><th>Brier</th></tr></thead><tbody>${Object.entries(e.subgroups||{}).flatMap(([kind,groups])=>Object.entries(groups).map(([name,g])=>`<tr><td>${esc(kind)} / ${esc(name)}${g.small_group?' · small sample':''}</td><td>${g.n}</td><td>${num(g.recall,3)}</td><td>${num(g.precision,3)}</td><td>${num(g.brier,3)}</td></tr>`)).join('')}</tbody></table></div><p>${esc(e.limitations||'Synthetic results only; not evidence of real-world effectiveness.')}</p></details>`;}catch(error){if($('#modelEvidence'))$('#modelEvidence').textContent=error.message;}
}

async function showAudit(focusId) {
 closeDialogs();openModal(dialogHead('APPEND-ONLY RECORD','The decision history.')+`<div class="dialog-body"><p>Imports, review versions and report exports are recorded. Original proposals and earlier reviews are preserved.</p><div id="auditEvents">Loading audit events…</div></div>`,true);
 try{const {events}=await api('/audit/events?limit=200');if(!$('#auditEvents'))return;$('#auditEvents').innerHTML=events.length?events.map(e=>`<div class="audit-row" id="event-${e.id}"><strong>#${e.id} · ${esc(e.event)}</strong><small>${esc(e.entity_id)} · ${esc(new Date(e.created_at).toLocaleString('en-GB',{timeZone:'Africa/Lagos'}))} WAT</small><p class="subtle-caption">${esc(JSON.stringify(e.metadata))}</p></div>`).join(''):'<p>No events recorded.</p>';if(focusId)$(`#event-${focusId}`)?.scrollIntoView({block:'center'});}catch(error){if($('#auditEvents'))$('#auditEvents').textContent=error.message;}
}

function reportRequest() {
 $$('.action-item').forEach(row=>updateActionRow(row));
 const used=state.draft.actions.filter(a=>a.action||a.owner||a.due_date);
 for(const a of used){if((a.action||'').trim().length<5||!a.owner?.trim()||!a.due_date)throw new Error('Each action needs a description, owner and due date. Complete the action register before exporting.');}
 if(!state.draft.prepared_by.trim())throw new Error('Enter who prepared the report.');
 return {...state.draft,actions:used,window:state.window};
}
function updateActionRow(row) {
 const id=row.dataset.actionRow;const item={finding_id:id};$$('[data-action-field]',row).forEach(el=>{item[el.dataset.actionField]=el.value;});const idx=state.draft.actions.findIndex(a=>a.finding_id===id);if(idx<0)state.draft.actions.push(item);else state.draft.actions[idx]=item;
}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function fullReport(download=false) {
 const response=await api(`/reports/action-report?download=${download}`,{method:'POST',body:JSON.stringify(reportRequest()),raw:true});
 const html=await response.text();if(download){downloadBlob(new Blob([html],{type:'text/html'}),'medflow-district-action-report.html');toast('The complete 13-section HTML report was exported.');return;}
 openModal(dialogHead('DISTRICT MEDICINE-SUPPLY BRIEF','The complete supply brief.')+`<div class="dialog-body"><div class="button-row"><button class="button secondary" data-action="print-report">Print / save PDF ↗</button><button class="button secondary" data-action="download-report">Export HTML ↓</button></div><p class="subtle-caption top-gap">Supply risks · readiness · resources · next decisions</p><iframe id="reportFrame" class="full-report-preview" title="Complete 13-section district performance report"></iframe></div>`,true);
 $('#reportFrame').srcdoc=html;
}

document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action,id=el.dataset.id;
 try{
  if(action==='window'){state.window=Number(el.dataset.window);el.disabled=true;state.email=null;state.monitor=null;state.copilotAnswer=null;await refresh();announce(`Updated to ${state.window}-day horizon.`);}
  else if(action==='import')showImport();
  else if(action==='close-dialog')el.closest('dialog').close();
  else if(action==='detail')showDetail(id);
  else if(action==='review')showReview(id);
  else if(action==='planner'){closeDialogs();location.hash='planner';}
  else if(action==='quality'){location.hash='quality';}
  else if(action==='high-risks'){state.filters.risk='high';location.hash='risks';if(state.page==='risks')render();}
  else if(action==='weak-evidence'){state.filters.risk='not_assessed';location.hash='risks';if(state.page==='risks')render();}
  else if(action==='clear-filters'){Object.keys(state.filters).forEach(k=>state.filters[k]='');render();}
  else if(action==='remove-filter'){state.filters[el.dataset.filter]='';render();}
  else if(action==='planner-tab'){state.plannerTab=el.dataset.tab;render();}
  else if(action==='report-tab'){state.reportTab=el.dataset.tab;render();}
  else if(action==='copilot'){await showAssistance('Draft a concise district supply brief.','Draft the supply brief.');}
  else if(action==='assist-risk'){const p=state.data.pairs.find(p=>p.finding_id===id);await showAssistance(`Why is ${p.facility} / ${p.medicine} classified at this risk level?`,'Explain this risk.',{finding_id:id});}
  else if(action==='assist-plan'){await showAssistance('Which transfer options comply with the safety-stock policy?','Review the transfer evidence.',id?{recommendation_id:id}:{});}
  else if(action==='assist-quality'){await showAssistance('Summarise the reporting gaps and evidence quality issues.','Prioritise reporting corrections.');}
  else if(action==='monitor'){closeDialogs();state.aiTab='monitoring';location.hash='ai';await loadMonitoring();render();}
  else if(action==='ai-tab'){state.aiTab=el.dataset.tab;if(state.aiTab==='monitoring')await loadMonitoring();render();}

  else if(action==='refresh-monitor'){el.disabled=true;await loadMonitoring();render();}
  else if(action==='source'){if(el.dataset.type==='finding'){closeDialogs();showDetail(id);}else if(el.dataset.type==='recommendation')showReview(id);else await showMethod();}
  else if(action==='method')await showMethod();
  else if(action==='audit')await showAudit(id);
  else if(action==='add-report'){state.draft.selected_findings=[...new Set([...(state.draft.selected_findings||state.data.pairs.filter(p=>p.risk==='high').map(p=>p.finding_id)),id])];closeDialogs();state.reportTab='briefing';location.hash='report';toast('Finding included in the working report.');}
  else if(action==='load-demo'){el.disabled=true;el.textContent='Validating demonstration…';await api('/data/demo',{method:'POST'});state.draftLoaded=false;state.email=null;await refresh();closeDialogs();toast('Demonstration loaded. Invalid source evidence is quarantined.');}
  else if(action==='save-draft'){el.disabled=true;await api('/reports/draft',{method:'PUT',body:JSON.stringify(reportRequest())});toast('Working draft and action assignments saved.');}
  else if(action==='full-report')await fullReport(false);
  else if(action==='download-report')await fullReport(true);
  else if(action==='print-report')$('#reportFrame').contentWindow.print();
  else if(action==='generate-narrative'){el.disabled=true;state.aiDraft=await api('/ai/narrative',{method:'POST',body:JSON.stringify(reportRequest())});state.reportTab='briefing';render();toast(state.aiDraft.mode==='gemini'?'Draft checked against the approved evidence.':state.aiDraft.reason);}
  else if(action==='generate-email'){el.disabled=true;state.email=await api('/reports/escalation',{method:'POST',body:JSON.stringify(reportRequest())});render();announce('Separate escalation draft generated. No email was sent.');}
  else if(action==='download-email'){const response=await api('/reports/escalation?download=true',{method:'POST',body:JSON.stringify(reportRequest()),raw:true});downloadBlob(await response.blob(),'medflow-escalation-draft.eml');toast('Email draft downloaded. No email was sent.');}
  else if(action==='copy-email'){await navigator.clipboard.writeText(`Subject: ${state.email.subject}\n\n${state.email.body}`);toast('Escalation draft copied.');}
  else if(action==='suggest-actions'){const due=new Date(state.data.context.cutoff+'T12:00:00');due.setDate(due.getDate()+5);state.draft.actions=chosenFindings().filter(p=>p.risk==='high').map(p=>({finding_id:p.finding_id,action:'Validate the usable balance, confirm delivery dates and review the feasible redistribution proposal.',owner:'District pharmacist / logistics lead',due_date:due.toISOString().slice(0,10),status:'open'}));render();toast('Suggested actions populated. Review the assignments before saving.');}
 }catch(error){showError(error.message,el.closest('dialog')||document);}
 finally{if(el.isConnected)el.disabled=false;}
});

document.addEventListener('change',event=>{
 const el=event.target;
 if(el.dataset.draft){state.draft[el.dataset.draft]=el.value;state.aiDraft=null;state.email=null;}
 if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;render();$(`[data-filter="${el.dataset.filter}"]`)?.focus();}
 if(el.name==='decision'){const field=$('#editQuantityField');field.hidden=el.value!=='edited';$('#reviewQuantity').required=el.value==='edited';}
 if(el.matches('[data-finding]')){if(state.draft.selected_findings===null)state.draft.selected_findings=state.data.pairs.map(p=>p.finding_id);if(el.checked)state.draft.selected_findings=[...new Set([...state.draft.selected_findings,el.dataset.finding])];else state.draft.selected_findings=state.draft.selected_findings.filter(x=>x!==el.dataset.finding);state.email=null;render();}
 if(el.matches('[data-all-findings]')){state.draft.selected_findings=el.checked?null:[];state.email=null;render();}
});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.draft){state.draft[el.dataset.draft]=el.value;state.email=null;}if(el.dataset.actionField)updateActionRow(el.closest('[data-action-row]'));});

document.addEventListener('submit',async event=>{
 const form=event.target;if(!['reviewForm','importForm'].includes(form.id))return;event.preventDefault();const submit=$('button[type=submit]',form);submit.disabled=true;$('[data-error]',form).hidden=true;
 try{
  if(form.id==='reviewForm'){
   const r=state.data.planner.recommendations.find(r=>r.recommendation_id===form.dataset.id),data=new FormData(form),decision=data.get('decision');
   const request={decision,reviewer:data.get('reviewer'),note:data.get('note'),expected_version:r.version,acknowledged:data.has('acknowledged')};
   if(decision==='edited')request.quantity=Number(data.get('quantity'));
   const result=await api(`/redistribution/${r.recommendation_id}/review?window=${state.window}`,{method:'POST',body:JSON.stringify(request)});
   await refresh();$('#modalContent').innerHTML=dialogHead('DECISION RECORDED','A traceable next step.')+`<div class="dialog-body"><div class="form-success">Review version ${result.version} recorded. No stock has moved.</div><p>Your rationale and the original proposal are preserved. Any operational transfer follows the authorised external process.</p><button class="text-link" data-action="audit" data-id="${result.audit_id}">View audit event #${result.audit_id} ↗</button></div><div class="dialog-footer"><button class="button" data-action="close-dialog">Return to the workspace</button></div>`;decorateIcons($('#modal'));announce('Review decision recorded. No stock has moved.');
  }else{
   const data=new FormData(form);for(const [,file] of data){if(file instanceof File&&file.size>8388608)throw new Error(`${file.name} exceeds the 8 MB file limit.`);}data.append('schema_version','1.0.0');
   const result=await api('/data/import',{method:'POST',body:data});if(result.approved){state.email=null;state.draftLoaded=false;await refresh();}
   $('#modalContent').innerHTML=dialogHead('VALIDATION COMPLETE',result.approved?'Evidence ready for review.':'Import withheld.')+`<div class="dialog-body"><div class="${result.approved?'form-success':'form-error'}">${num(result.accepted)} accepted rows · ${result.rejected.length} rejected rows. ${result.approved?'The validated dataset is active.':'Critical reference or inventory data is missing. The previous active dataset is retained.'}</div>${result.rejected.length?`<table class="report-mini-table"><thead><tr><th>Source row</th><th>Rule</th><th>Reason</th></tr></thead><tbody>${result.rejected.slice(0,12).map(r=>`<tr><td>${esc(r.entity)} / ${r.row}</td><td>${esc(r.rule)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table>`:''}<p class="subtle-caption top-gap">Import ${esc(result.import_id)} · available through the import-status API.</p></div><div class="dialog-footer"><button class="button secondary" data-action="import">Import another bundle</button><button class="button" data-action="close-dialog">Return to workspace</button></div>`;
  }
 }catch(error){showError(error.message,form);}finally{if(submit.isConnected)submit.disabled=false;}
});

window.addEventListener('hashchange',async()=>{
 if(location.hash==='#report'&&!state.draftLoaded){try{const draft=await api('/reports/draft');if(Object.keys(draft).length)state.draft={...state.draft,...draft};state.draftLoaded=true;}catch(error){toast(error.message);}}
 render();window.scrollTo(0,0);
});
$$('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}}));

(async()=>{try{await refresh();if(location.hash==='#report'){const draft=await api('/reports/draft');if(Object.keys(draft).length)state.draft={...state.draft,...draft};state.draftLoaded=true;render();}}catch(error){$('#main').innerHTML=`<div class="empty"><div class="section-overline">WORKSPACE UNAVAILABLE</div><h2>The briefing could not be loaded.</h2><p>${esc(error.message)}</p><button class="button" id="retryButton">Try again →</button></div>`;$('#retryButton').onclick=()=>location.reload();}})();

function aiPage() { return heading('ai')+monitoringView(); }

async function loadMonitoring(){state.monitor=await api(`/monitoring/summary?window=${state.window}`);}
function monitoringView(){
 const d=state.monitor;if(!d)return `<div class="empty"><h2>Inspect the model record.</h2><p>Load time-based holdout metrics, live review feedback and feature-shift indicators for the current horizon.</p><button class="button" data-action="refresh-monitor">Load monitoring evidence</button></div>`;
 const e=d.evaluation,m=e.test?.by_horizon?.[state.window]||e.test?.model||{},f=d.feedback;
 return `<div class="note-band"><p><strong>Synthetic evaluation · ${esc(e.version)}.</strong> ${esc(d.outcome_note)}</p><button class="text-link" data-action="refresh-monitor">Refresh evidence ${icon('clock',14)}</button></div><div class="monitor-metrics">${[['Recall',pct(m.recall||0,1),'Detected labelled stock-outs'],['Precision',pct(m.precision||0,1),'Alerts that matched a stock-out'],['PR-AUC',num(m.pr_auc,3),'Probability ranking'],['Brier score',num(m.brier,4),'Probability calibration error']].map(([label,value,note])=>`<div class="monitor-metric"><label>${label} · ${state.window}-day holdout</label><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><section class="monitor-section"><div class="section-heading"><h2>The validation decision.</h2><span class="subtle-caption">TEST DATA EXCLUDED FROM MODEL SELECTION</span></div><p class="subtle-caption">${esc(e.promotion?.reason||'')} ${esc(e.threshold_rationale||'')}</p><div class="table-scroll"><table class="risk-table"><thead><tr><th>Candidate</th><th>Validation recall</th><th>Precision</th><th>PR-AUC</th><th>Brier</th><th>Decision</th></tr></thead><tbody>${Object.entries(e.validation_models||{}).map(([name,v])=>`<tr><td>${esc(name.replaceAll('_',' '))}</td><td>${pct(v.operating_point.recall,1)}</td><td>${pct(v.operating_point.precision,1)}</td><td>${num(v.operating_point.pr_auc,3)}</td><td>${num(v.operating_point.brier,4)}</td><td>${badge(name===e.selected_model?'accepted':'pending',name===e.selected_model?'Selected for scoring':'Benchmark')}</td></tr>`).join('')}<tr><td>Deterministic baseline</td><td>${pct(e.validation_baseline?.recall||0,1)}</td><td>${pct(e.validation_baseline?.precision||0,1)}</td><td>${num(e.validation_baseline?.pr_auc,3)}</td><td>${num(e.validation_baseline?.brier,4)}</td><td>Conservative alert retained</td></tr></tbody></table></div></section><div class="monitor-two"><section class="monitor-section"><div class="section-overline">HUMAN FEEDBACK · CURRENT HORIZON</div><h2>Review is part of the record.</h2><div class="monitor-feedback">${[['accepted','Accepted'],['edited','Edited'],['rejected','Rejected'],['pending','Pending']].map(([k,l])=>`<div><strong>${f[k]}</strong><label>${l}</label></div>`).join('')}</div><p class="subtle-caption">${f.reviewed} of ${f.total} proposals reviewed · ${f.review_rate==null?'N/A':pct(f.review_rate,1)} of the 100% review target. Every decision retains a rationale, version and audit event. It does not execute a transfer.</p><button class="text-link" data-action="audit">Inspect review history ${icon('clock',14)}</button></section><section class="monitor-section"><div class="section-overline">CALIBRATION · COMBINED HOLDOUT</div><h2>Probability against outcomes.</h2><table class="report-mini-table"><thead><tr><th>Mean predicted probability</th><th>Observed stock-out rate</th></tr></thead><tbody>${(e.test?.calibration?.mean_prediction||[]).map((v,i)=>`<tr><td>${pct(v,2)}</td><td>${pct(e.test.calibration.observed_rate[i],2)}</td></tr>`).join('')}</tbody></table><p class="subtle-caption top-gap">Quantile bins on the untouched synthetic holdout. Small groups have substantial uncertainty; these figures do not establish real-world effectiveness.</p></section></div><section class="monitor-section"><div class="section-heading"><h2>What has shifted in the evidence.</h2><span class="subtle-caption">CURRENT DATA VS TRAINING REFERENCE</span></div><p class="subtle-caption">${esc(d.drift_note)}</p><div class="table-scroll"><table class="risk-table"><thead><tr><th>Feature</th><th>Actual current mean</th><th>Training mean</th><th>Standardised shift</th><th>Status</th></tr></thead><tbody>${d.drift.map(r=>`<tr><td>${esc(r.feature.replaceAll('_',' '))}</td><td>${num(r.current_mean,2)}</td><td>${num(r.training_mean,2)}</td><td>${r.standardised_shift==null?'New value in constant feature':num(r.standardised_shift,2)}</td><td>${badge(r.flagged?'medium':'accepted',r.flagged?'Investigate':'Within trigger')}</td></tr>`).join('')}</tbody></table></div></section><section class="monitor-section"><h2>Subgroup performance.</h2><div class="table-scroll"><table class="risk-table"><thead><tr><th>Group</th><th>n / positives</th><th>Recall</th><th>Precision</th><th>Brier</th></tr></thead><tbody>${Object.entries(e.subgroups||{}).flatMap(([kind,groups])=>Object.entries(groups).map(([name,g])=>`<tr><td>${esc(kind.replaceAll('_',' '))} / ${esc(name)}${g.small_group?' · small sample':''}</td><td>${g.n} / ${g.positives}</td><td>${pct(g.recall,1)}</td><td>${pct(g.precision,1)}</td><td>${num(g.brier,4)}</td></tr>`)).join('')}</tbody></table></div><p class="subtle-caption top-gap">${esc(e.limitations||'')}</p></section>`;
}

async function showAssistance(question,title,scope={}) {
 closeDialogs();
 openModal(dialogHead('SOURCE-BASED DECISION SUPPORT',title)+`<div class="dialog-body"><p>Review the explanation alongside its source records. The quantities and safety checks remain unchanged.</p><div id="assistanceContent"><div class="loading-line"></div><p class="top-gap">Reviewing the current findings…</p></div></div>`,true);
 try {
  const result=await api('/copilot/ask',{method:'POST',body:JSON.stringify({question,window:state.window,use_gemini:true,...scope})});
  if(!$('#assistanceContent'))return;
  $('#assistanceContent').innerHTML=`<div class="section-overline">WORKING DRAFT · REVIEW REQUIRED</div><h3>${esc(result.title)}</h3>${result.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="copilot-sources"><div class="section-overline">SOURCE RECORDS</div>${result.sources.map(s=>`<button class="source-chip" data-action="source" data-type="${s.type}" data-id="${esc(s.id)}">[${esc(s.id)}] ${esc(s.label)}</button>`).join('')}</div><details class="chart-alt top-gap"><summary>Draft provenance</summary><p>${result.mode==='gemini'?esc(result.model||'Gemini')+' selected and sequenced approved facts.':'Source-based draft; external drafting was unavailable.'} No new quantities were calculated. All recommendations require review.</p></details>`;
 } catch(error){if($('#assistanceContent'))$('#assistanceContent').textContent=error.message;}
}
